-- Generated by model/lib/sql/generate.mjs. L1's load of IMPORT Standard Cost from cells/IMPORT Standard Cost.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/IMPORT Standard Cost.csv
INSERT INTO "IMPORT Standard Cost" SELECT coalesce(k0."SKU", fpabench_error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Years" k1 ON k1.name = c."Years"
GROUP BY 1, 2;
ANALYZE "IMPORT Standard Cost";
